export const getListAdminBillingPricesUrl = (
  sku: string,
  params?: ListAdminBillingPricesParams,
) => {
  const normalizedParams = new URLSearchParams()

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  })

  const stringifiedParams = normalizedParams.toString()

  return stringifiedParams.length > 0
    ? `/admin/billing/skus/${encodeURIComponent(String(sku))}/prices?${stringifiedParams}`
    : `/admin/billing/skus/${encodeURIComponent(String(sku))}/prices`
}

